mapper.update:
UPDATE scene_step_run
SET status = 'SUCCESS',
    finished_at = #{finishedAt,jdbcType=TIMESTAMP},
    updated_at = #{finishedAt,jdbcType=TIMESTAMP}
WHERE id = #{id}
  AND status = 'RUNNING'

UPDATE scene_step_run
SET status = 'SKIPPED',
    finished_at = #{finishedAt,jdbcType=TIMESTAMP},
    updated_at = #{finishedAt,jdbcType=TIMESTAMP}
WHERE id = #{id}
  AND status = 'PENDING'
